// tweenCamera puzzle
function tweenCamera(posOrObj, targetOrObj, duration, doSlot, movementType) {
    var camera = appInstance.getCamera();

    if (Array.isArray(posOrObj)) {
        var worldPos = _pGlob.vec3Tmp.fromArray(posOrObj);
        worldPos = PzLib.transformCoordsSpace(worldPos,
                PzLib.getSceneCoordSystem(), 'Y_UP_RIGHT');
    } else if (posOrObj) {
        var posObj = PzLib.getObjectByName(posOrObj);
        if (!posObj) return;
        var worldPos = posObj.getWorldPosition(_pGlob.vec3Tmp);
    } else {
        // empty input means: don't change the position
        var worldPos = camera.getWorldPosition(_pGlob.vec3Tmp);
    }

    if (Array.isArray(targetOrObj)) {
        var worldTarget = _pGlob.vec3Tmp2.fromArray(targetOrObj);
        worldTarget = PzLib.transformCoordsSpace(worldTarget,
                PzLib.getSceneCoordSystem(), 'Y_UP_RIGHT');
    } else {
        var targObj = PzLib.getObjectByName(targetOrObj);
        if (!targObj) return;
        var worldTarget = targObj.getWorldPosition(_pGlob.vec3Tmp2);
    }

    duration = Math.max(0, duration);

    if (appInstance.controls && appInstance.controls.tween) {
        // orbit and flying cameras
        if (!appInstance.controls.inTween) {
            appInstance.controls.tween(worldPos, worldTarget, duration, doSlot,
                    movementType);
        }
    } else {
        // TODO: static camera, just position it for now
        if (camera.parent) {
            camera.parent.worldToLocal(worldPos);
        }
        camera.position.copy(worldPos);
        camera.lookAt(worldTarget);
        doSlot();
    }
}

// Describe this function...
function anotaciones_secundarias(titulo_es, titulo_en, objeto_referencia, objeto_referencia_2, id, objeto, camara, camara_direccion, proceso_actual) {
  crear_anotacion(objeto_referencia, objeto_referencia_2, id, titulo_en, titulo_es);
  eventHTMLElem('mouseenter', id, false, function(event) {
    if (enfocado == 'no') {
      mouseEnter(id);
      outline(objeto, 'ENABLE');
    }
  });
  eventHTMLElem('mouseleave', id, false, function(event) {
    if (enfocado == 'no') {
      mouseLeave(id);
    }
  });
  eventHTMLElem('click', id, false, function(event) {
    handleAnnot(false, '', ['ALL_OBJECTS'], '', '', undefined);
    proceso = proceso_actual;
    handleAnnot(true, '', objeto_referencia, '', id, undefined);
    addHTMLElement('div', String(id) + 'en', 'TO', id, false);
    addHTMLElement('div', String(id) + 'es', 'TO', id, false);
    setHTMLElemAttribute('textContent', titulo_en, String(id) + 'en', false);
    setHTMLElemAttribute('textContent', titulo_es, String(id) + 'es', false);
    setHTMLElemAttribute('className', 'en', String(id) + 'en', false);
    setHTMLElemAttribute('className', 'es', String(id) + 'es', false);
    if (enfocado == 'no') {
      reproducir_anotacion(id);
      click();
      enfocado = 'si';
      tweenCamera(camara, camara_direccion, 1, function() {
        outline(objeto, 'ENABLE');
      }, 0);
    }
  });
}

